package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim a person makes on a sheet: an amount (0.00 or more), a date, a note, a status and, once opened, a number. */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The sheet's number for the claim, given when it is opened and kept once voided; none while a draft. */
    @Column(name = "claim_number")
    private Integer number;

    /** What was due on the claim when it was settled; none until then, or if its grade had no rate. */
    @Column(name = "settled_due", precision = 12, scale = 2)
    private BigDecimal settledDue;

    /** Who opened the claim; none while it is a draft. */
    @Column(name = "opened_by")
    private String openedBy;

    /** Whether the claim is bound to the figure it had at its person's last statement. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The figure the claim was bound to at its person's last statement; none when it was n/a then. */
    @Column(name = "stated_due", precision = 12, scale = 2)
    private BigDecimal statedDue;

    protected Claim() {}

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public Integer getNumber() {
        return number;
    }

    public void setNumber(Integer number) {
        this.number = number;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** Bind the claim to a figure (none for n/a). */
    public void bind(BigDecimal due) {
        this.stated = true;
        this.statedDue = due;
    }

    /** Leave the claim unbound, live again. */
    public void unbind() {
        this.stated = false;
        this.statedDue = null;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RollupService rollup;
    private final SheetService sheets;
    private final PeriodService periods;
    private final SettingService settings;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, PersonRepository people, RollupService rollup, SheetService sheets,
            PeriodService periods, SettingService settings, Audit audit) {
        this.claims = claims;
        this.people = people;
        this.rollup = rollup;
        this.sheets = sheets;
        this.periods = periods;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's claims, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        sheets.today(sheetId); // the sheet must exist
        return claims.findBySheetIdOrderByIdDesc(sheetId);
    }

    /** Add a claim for a person; a claim without a date is dated the sheet's today. One dated in a closed period
     * is refused. */
    @Transactional
    public Claim add(String user, String sheetId, Long personId, BigDecimal amount, LocalDate date, String note) {
        LocalDate today = sheets.today(sheetId);
        Person person = requirePerson(sheetId, personId);
        requireNotRetired(person, date != null ? date : today);
        requireOpenPeriod(sheetId, date != null ? date : today);
        Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.saveAndFlush(
                new Claim(sheetId, personId, amount, date != null ? date : today, noteOf(note)));
        audit.recordOnCommit(entry("CLAIM_ADDED", user, person, claim));
        rollup.recordChanges(user, sheetId, before);
        return claim;
    }

    /** Edit a claim; only a draft can be edited (an open claim is voided and added again instead), and one dated
     * in a closed period, or that would be, is refused. */
    @Transactional
    public Claim update(String user, String sheetId, Long id, BigDecimal amount, LocalDate date, String note) {
        LocalDate today = sheets.today(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can be edited.");
        }
        requireOpenPeriod(sheetId, claim.getDate());
        requireOpenPeriod(sheetId, date != null ? date : today);
        requireNotRetired(requirePerson(sheetId, claim.getPersonId()), date != null ? date : today);
        Snapshot before = rollup.snapshot(sheetId);
        claim.setAmount(amount);
        claim.setDate(date != null ? date : today);
        claim.setNote(noteOf(note));
        claims.flush();
        audit.recordOnCommit(entry("CLAIM_EDITED", user, requirePerson(sheetId, claim.getPersonId()), claim));
        rollup.recordChanges(user, sheetId, before);
        return claim;
    }

    /** Move a claim to another status; a change its status does not allow, or of a claim dated in a closed
     * period, is refused; so is a settle by a clerk of a claim whose due is above the clerk limit. */
    @Transactional
    public Claim changeStatus(String user, String sheetId, Long id, ClaimStatus next) {
        sheets.today(sheetId); // the sheet must exist
        // Taking the number first locks the sheet, so claims are opened one at a time; a refused
        // open rolls back and gives the number back.
        Integer number = next == ClaimStatus.OPEN ? sheets.nextClaimNumber(sheetId) : null;
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
        requireOpenPeriod(sheetId, claim.getDate());
        if (!claim.getStatus().canBecome(next)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
        }
        // Four eyes: whoever opened a claim cannot also settle it.
        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it.");
        }
        Person person = requirePerson(sheetId, claim.getPersonId());
        // A clerk settles only a claim whose due is within the sheet's clerk limit.
        if (next == ClaimStatus.SETTLED) {
            settings.requireMaySettle(sheetId, user, figureOf(claim, person.getGrade()));
        }
        Snapshot before = rollup.snapshot(sheetId);
        claim.setStatus(next);
        if (next == ClaimStatus.OPEN) {
            claim.setNumber(number);
            claim.setOpenedBy(user);
        }
        // A voided claim's line carries the number it had.
        String entry = entry(EVENTS.get(next), user, person, claim);
        if (next == ClaimStatus.SETTLED) {
            // Settling fixes the due at the figure the claim has: the one its last statement bound it to, else
            // the rate its grade has on its date; with no figure it stays live.
            claim.setSettledDue(figureOf(claim, person.getGrade()));
            entry += " due=" + (claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : "n/a");
        }
        claims.flush();
        audit.recordOnCommit(entry);
        rollup.recordChanges(user, sheetId, before);
        return claim;
    }

    private static final Map<ClaimStatus, String> EVENTS = Map.of(
            ClaimStatus.OPEN, "CLAIM_OPENED",
            ClaimStatus.SETTLED, "CLAIM_SETTLED",
            ClaimStatus.VOID, "CLAIM_VOIDED");

    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to,
     * else what is due at its grade's rate; none when that is n/a. */
    public BigDecimal figureOf(Claim claim, String grade) {
        return rollup.figureOf(claim, grade);
    }

    /** Refuse a change to a claim dated in a closed period. Locks the sheet first, so a period cannot close
     * while the change is made. */
    private void requireOpenPeriod(String sheetId, LocalDate date) {
        sheets.lock(sheetId);
        periods.requireOpen(sheetId, date);
    }

    /** Refuse a claim dated after its person's retirement. */
    private static void requireNotRetired(Person person, LocalDate date) {
        if (person.retiredOn(date)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    person.getName() + " is retired from " + person.getRetiredFrom() + ".");
        }
    }

    private Person requirePerson(String sheetId, Long personId) {
        return people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
    }

    /** The amount is written as the screen shows it, with two decimals; the date as yyyy-mm-dd; a
     * claim with a number ends with it. */
    private static String entry(String event, String user, Person person, Claim claim) {
        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (claim.getNumber() != null ? " number=" + claim.getNumber() : "");
    }

    private static String noteOf(String note) {
        return note == null ? "" : note.trim();
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's
 * claimed-total and due-total. A change takes them before it alters anything and hands them back after, and
 * every figure it moved is written to the audit after the change's own lines. Called within the change's
 * transaction.
 */
@Service
public class RollupService {

    /** Shown in place of a due-total whose grade has no rate. */
    private static final String NO_RATE = "n/a";

    /** A person's figures, as the screen shows them. */
    public record Figures(String name, String claimed, String dueTotal) {}

    /** The sheet's figures at one moment: each person's by id, in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {}

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures now; none (an empty sheet's) when there is no such sheet. */
    public Snapshot snapshot(String sheetId) {
        LocalDate today = sheets.findById(sheetId).map(s -> s.getToday()).orElse(null);
        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            byPerson.computeIfAbsent(claim.getPersonId(), k -> new ArrayList<>()).add(claim);
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Rate> gradeRates = rates.findBySheetIdAndGrade(sheetId, person.getGrade());
            List<Claim> counted = byPerson.getOrDefault(person.getId(), List.of()).stream()
                    .filter(c -> counts(c, person)).toList();
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            boolean frozen = false;
            for (Claim claim : counted) {
                claimed = claimed.add(claim.getAmount().setScale(2));
                frozen |= claim.getSettledDue() != null || claim.isStated();
                BigDecimal figure = figureOf(claim, gradeRates);
                if (figure != null) {
                    due = due.add(figure.setScale(2));
                }
            }
            // Like the screen: with no rate in force today and no claim keeping a figure, the due-total is n/a.
            boolean rated = today != null && Rate.inForce(gradeRates, today).isPresent();
            String personDue = rated || frozen ? due.toPlainString() : NO_RATE;
            claimedTotal = claimedTotal.add(claimed);
            if (rated || frozen) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(person.getId(), new Figures(person.getName(), claimed.toPlainString(), personDue));
        }
        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString());
    }

    /** The due-total of the sheet's claims that count (a held person's OPEN ones do not) dated from and to, inclusive: the sum of their figures,
     * n/a ones skipped. */
    public BigDecimal dueTotal(String sheetId, LocalDate from, LocalDate to) {
        Map<Long, List<Rate>> gradeRates = new LinkedHashMap<>();
        Map<Long, Person> byId = new LinkedHashMap<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            gradeRates.put(person.getId(), rates.findBySheetIdAndGrade(sheetId, person.getGrade()));
            byId.put(person.getId(), person);
        }
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            List<Rate> personRates = gradeRates.get(claim.getPersonId());
            if (personRates == null || !counts(claim, byId.get(claim.getPersonId()))
                    || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
                continue;
            }
            BigDecimal figure = figureOf(claim, personRates);
            if (figure != null) {
                total = total.add(figure.setScale(2));
            }
        }
        return total;
    }

    /**
     * Write to the audit, once the change commits, one ROLLUP line for each person whose figures moved since
     * {@code before} (a person new since then counts as moved), in the order they were added, then a TOTALS
     * line when the sheet's totals moved.
     */
    public void recordChanges(String user, String sheetId, Snapshot before) {
        claims.flush();
        Snapshot after = snapshot(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
            Figures now = e.getValue();
            Figures was = before.people().get(e.getKey());
            if (was != null && was.claimed().equals(now.claimed()) && was.dueTotal().equals(now.dueTotal())) {
                continue;
            }
            audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + now.claimed()
                    + " due-total=" + now.dueTotal());
        }
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal());
        }
    }

    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to,
     * else what is due at its grade's rate; none when that is n/a. */
    public BigDecimal figureOf(Claim claim, String grade) {
        return figureOf(claim, rates.findBySheetIdAndGrade(claim.getSheetId(), grade));
    }

    private static BigDecimal figureOf(Claim claim, List<Rate> gradeRates) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        return claim.isStated() ? claim.getStatedDue() : dueOf(claim, gradeRates);
    }

    /** What is due on a claim at the rate its grade has in force on the claim's date, rounded half to even to two
     * decimals; none when no rate of the grade applies then. */
    private static BigDecimal dueOf(Claim claim, List<Rate> gradeRates) {
        BigDecimal amount = claim.getAmount();
        return Rate.inForce(gradeRates, claim.getDate())
                .map(r -> amount.multiply(r.getRate()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
                .orElse(null);
    }

    /** Only OPEN and SETTLED claims count toward what is claimed and due; a held person's OPEN ones do not. */
    private static boolean counts(Claim claim, Person person) {
        return (claim.getStatus() == ClaimStatus.OPEN && !person.isHeld())
                || claim.getStatus() == ClaimStatus.SETTLED;
    }
}
