import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, map, tap } from 'rxjs';

interface User {
  name: string;
}

interface SheetView {
  id: string;
  today: string;
}

// Who is signed in and which sheet is active. Everything else in the app is kept per sheet, so
// features read `sheetId` and send `user` with their requests (the X-User header).
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  private readonly _user = signal<string | null>(null);
  private readonly _sheetId = signal<string | null>(null);
  readonly user = this._user.asReadonly();
  private readonly _today = signal<string | null>(null);
  readonly sheetId = this._sheetId.asReadonly();
  /** The active sheet's today (yyyy-mm-dd). Date-dependent features use this, never the clock. */
  readonly today = this._today.asReadonly();

  signIn(name: string): Observable<string> {
    return this.http.post<User>('/api/session', { name }).pipe(
      map((u) => u.name),
      tap((n) => {
        this._user.set(n);
        this._sheetId.set(null);
        this._today.set(null);
      }),
    );
  }

  loadSheet(id: string): Observable<string> {
    return this.http
      .post<SheetView>('/api/sheets/load', { id }, { headers: { 'X-User': this._user() ?? '' } })
      .pipe(
        tap((s) => {
          this._sheetId.set(s.id);
          this._today.set(s.today);
        }),
        map((s) => s.id),
      );
  }

  setToday(today: string): Observable<string> {
    const id = this._sheetId() ?? '';
    return this.http
      .put<SheetView>(
        `/api/sheets/${encodeURIComponent(id)}/today`,
        { today },
        { headers: { 'X-User': this._user() ?? '' } },
      )
      .pipe(
        tap((s) => {
          if (this._sheetId() === s.id) this._today.set(s.today);
        }),
        map((s) => s.today),
      );
  }
}
import { Component, inject } from '@angular/core';
import { Session } from '../../core/session';
import { People } from '../people/people';
import { Settings } from '../settings/settings';

// The home page: the active sheet's settings and people, once a sheet is loaded.
@Component({
  selector: 'app-home',
  imports: [People, Settings],
  template: `
    @if (session.sheetId()) {
      <app-settings />
      <app-people />
    } @else {
      <p data-testid="home-empty">Nothing here yet.</p>
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Session } from '../../core/session';
import { Grade } from '../people/people-api';
import { NO_RATE, Rate, dueOf, rateOn } from '../rates/rates-api';

export interface Claim {
  id: number;
  personId: number;
  /** With two decimals, e.g. "10.00". */
  amount: string;
  /** yyyy-mm-dd */
  date: string;
  note: string;
  status: ClaimStatus;
  /** The sheet's number for the claim, given when it is opened; null while a draft or once voided. */
  number: number | null;
  /** What was due when the claim was settled, with two decimals; null while it is live (not settled, or
   * settled when its grade had no rate). */
  due: string | null;
  /** Who opened the claim; null while it is a draft. */
  openedBy: string | null;
  /** Whether the claim is bound to the figure it had at its person's last statement. */
  stated: boolean;
  /** That bound figure, with two decimals; null when it was n/a or the claim is not bound. */
  statedDue: string | null;
}

/** A claim starts as DRAFT, is opened and then settled; a DRAFT or OPEN claim can be voided. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** The status changes a person can ask for on a claim. */
export type ClaimAction = 'open' | 'settle' | 'void';

/** Only OPEN and SETTLED claims count toward what is claimed and due. */
export function counts(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'SETTLED';
}

/** A settled claim's due is the figure it was settled at; a claim bound by its person's last statement shows
 * the figure it was bound to; any other is due at the rate its grade has now in force on the claim's date (n/a
 * when there is none). */
export function claimDue(claim: Claim, rates: readonly Rate[], grade: Grade): string {
  if (claim.due !== null) return claim.due;
  if (claim.stated) return claim.statedDue ?? NO_RATE;
  return dueOf(claim.amount, rateOn(rates, grade, claim.date));
}

/** Whether a claim keeps a figure whatever the rates: settled at one, or bound to one by a statement. */
export function keepsFigure(claim: Claim): boolean {
  return claim.due !== null || claim.stated;
}

export interface ClaimForm {
  amount: string;
  /** Null for the sheet's today. */
  date: string | null;
  note: string;
}
